update public.founder_profiles set display_name = 'Azizbek Rahimov', role_title = 'Asoschi, agronom', organization = '"AgroSmart Fargʻona" MChJ', location = 'Fargʻona', bio = 'Toshkent davlat agrar universiteti bitiruvchisi. 11 yildan beri Oʻzbekiston va Turkiyada issiqxona tizimlarini quradi.', registration_number = 'MChJ guvohnomasi № 309812490 (Fargʻona shahri)' where user_id = '8740db96-93af-407b-a6e6-82e6da721dd0';
update public.projects set location = 'Quva, Fargʻona viloyati', cover_image_path = '/images/fergana-agro.jpg', original_language = 'uz' where id = '9d4c480d-4f45-4f39-ad91-c4a1efa460b7';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 'uz', 'AgroSmart Fargʻona: quyosh energiyali gidroponik issiqxonalar', 'Quva tumanida suvni 78% kam sarflaydigan issiqxona — Fargʻona va Toshkent bozorlari uchun pomidor va qalampir.', 'Quva tumanida tomga oʻrnatilgan quyosh panellari bilan ishlaydigan gidroponik issiqxonalar quramiz. Yer osti suvi 78% kam sarflanadi, pomidor va bolgar qalampiri hosili esa ikki baravar oshadi.', 'Fargʻona vodiysida suv yildan-yilga kamaymoqda, ariq usulida sugʻorish esa suvning katta qismini isrof qiladi. Biz Quvadagi tajriba issiqxonamizda ikki mavsum yopiq tsiklli gidroponikani sinab koʻrdik: kimyoviy chiqindi yoʻq, suv sarfi toʻrt barobar kam.

Endi har biri 1 200 kv. metrlik uchta tijorat issiqxonasini qurmoqchimiz. Mablagʻ poʻlat karkas, polikarbonat, quyosh panellari va sugʻorish uskunalariga ketadi.

Bu mushoraka loyihasi: sarmoyadorlar 5 yil davomida tekshirilgan sof foydaning 28 foizini har chorakda oladi. Zarar boʻlsa, u ham kiritilgan ulushga qarab taqsimlanadi. Muddat oxirida kooperativ aʼzolari ulushni sotib olishi mumkin.', 'Fargʻonada qishda harorat baʼzan -10°C gacha tushadi. Shuning uchun ikki qavatli issiqlik izolyatsiyasi va pellet isitgichlar oʻrnatamiz. Yoʻlda hosil buzilmasligi uchun vakuum qadoqlashdan foydalanamiz.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = '9d4c480d-4f45-4f39-ad91-c4a1efa460b7')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
