update public.milestones set title = 'Yer tekislash va poydevor', description = 'Quvadagi yer uchastkasida beton poydevor va drenaj ariqlarini tayyorlash.', target_label = '1-oy' where id = 'be7dce6a-4e8d-4b13-ac50-14dd52d408b7';
update public.milestones set title = 'Karkas va quyosh panellari', description = 'Poʻlat karkasni oʻrnatish, polikarbonat bilan qoplash, panellarni ulash.', target_label = '2-oy' where id = 'b9571c77-72ae-452b-ad93-0d4931838058';
update public.milestones set title = 'Sugʻorish tizimi va birinchi ekin', description = 'Tomchilatib sugʻorishni oʻrnatish, oʻgʻit sinovi, birinchi koʻchatlarni ekish.', target_label = '3-oy' where id = 'f5f92d7f-2d13-445c-a61d-0b5dc1e0b8d6';
update public.milestones set title = 'Birinchi hosil va yetkazib berish', description = 'Toshkentdagi hamkor doʻkonlarga 12 tonna oliy navli hosil topshirish.', target_label = '5-oy' where id = '001387d4-9e9e-46c7-a875-a38aa15bdefa';
update public.equity_terms set projected_annual_return = '2,5 mln soʻm ulushga yiliga ~540–650 ming soʻm' where project_id = '9d4c480d-4f45-4f39-ad91-c4a1efa460b7';
update public.evaluations set summary = 'Fargʻona va Toshkent ulgurji bozorlari bilan tuzilgan yetkazib berish shartnomalari tasdiqlandi. Yer ijarasi hujjatlari va kredit tarixi tekshirildi — muammo yoʻq.', strengths = array['Asoschining Quvada qurgan oldingi issiqxonalari joyida koʻrildi', 'Suv tejash har oylik kommunal xarajatni ~70% kamaytiradi', 'Toshkentdagi 2 ta distribyutor bilan oldindan kelishuv bor'], risks = array['Qishki sovuqda qoʻshimcha isitish zaxirasi kerak', 'Sovutgichli transport yoʻlda ushlanib qolsa, hosil buzilishi mumkin'] where project_id = '9d4c480d-4f45-4f39-ad91-c4a1efa460b7';
update public.project_updates set title = 'Poydevor tayyor, quyosh panellari yetib keldi', body = 'Quvadagi poydevor toʻliq qotdi. Kecha texnik guruhimiz quyosh panellari va invertorlarni tekshirdi — barcha elektr sinovlaridan oʻtdi.' where id = '89e08185-355a-4cc7-a12c-510589d0f213';
update public.comments set body = 'Poydevor ishlari zoʻr ketyapti. Choraklik foyda qachon toʻlanadi?' where id = 'c34f5a57-adbb-4716-a157-c8c9a4b0a444';
update public.comments set body = 'Assalomu alaykum, Farrux! Har chorak yopilgandan keyin 15 kun ichida, tekshirilgan savdo hisoboti bilan birga toʻlanadi.' where id = '806a0fe3-7c08-4737-ad41-efab6bafda9d';
update public.founder_profiles set display_name = 'Dilnoza Karimova', role_title = 'Kooperativ rahbari, usta toʻquvchi', organization = 'Samarqand hunarmandlar uyushmasi', location = 'Samarqand', bio = '19 yillik tajribaga ega usta toʻquvchi. Oʻzbek amaliy sanʼatini YUNESKO koʻrgazmalarida namoyish etgan.', registration_number = 'YaTT guvohnomasi № 419203814 (Samarqand)' where user_id = '7d0a2834-cab2-43b3-a362-4e3793f49478';
update public.projects set location = 'Samarqand', cover_image_path = '/images/samarkand-craft.jpg', original_language = 'uz' where id = 'e1419726-cc75-4e37-a75a-8219566f2ff7';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('e1419726-cc75-4e37-a75a-8219566f2ff7', 'uz', 'Samarqand atlas va kulolchilik ustaxonasi', '24 nafar usta toʻquvchi va kulolga zamonaviy uskunalar, 18 nafar yosh shogirdga ish oʻrgatamiz.', 'Samarqanddagi ustalar kooperativi tabiiy boʻyoqli ipak abrbandi matolar va anʼanaviy kobalt sirli sopol buyumlar ishlab chiqarishni kengaytiradi hamda 18 nafar yosh shogird tayyorlaydi.', 'Qoʻlda toʻqilgan ipak atlas va sirli sopol — Buyuk ipak yoʻlidan qolgan meros. Lekin ustalarda koʻpincha xom ipakni ulgurji sotib olish, tejamkor elektr pech olish va buyumni yaxshi qadoqlash uchun pul yetmaydi.

Kooperativimiz 24 nafar usta oilasini bitta ustaxonaga birlashtirdi. Margʻilon pillasini toʻgʻridan-toʻgʻri olamiz va tutunsiz elektr pechga oʻtamiz — eski sir retseptlari saqlanib qoladi.

Homiylar raqamlangan buyumlar oladi: qoʻlda toʻqilgan ipak roʻmol, usta muhri bosilgan sopol toʻplam va Samarqanddagi ustaxonamizda master-klass.', 'Bir metr ipakni qoʻlda toʻqish 4–6 soat oladi. Mukofotlar oʻz vaqtida yetishi uchun dastgohlarni 8 nafar katta usta oʻrtasida taqsimladik.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = 'e1419726-cc75-4e37-a75a-8219566f2ff7')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
