update public.evaluations set summary = 'Ustalarning ishlab chiqarish hajmi tasdiqlangan. Mukofotlar tannarxi aniq hisoblangan, loyiha hunarmandchilikni rivojlantirish dasturiga mos.', strengths = array['Asoschi YUNESKO koʻrgazmalarida qatnashgan, tan olingan usta', 'Mahalliy xaridorlar va sayyohlardan barqaror talab bor', 'Margʻilon ipak ishlab chiqaruvchilaridan toʻgʻridan-toʻgʻri xarid — vositachi ustamasi yoʻq'], risks = array['Tabiiy boʻyoq rangini saqlash uchun xona harorati nazorat qilinishi kerak', 'Sopolni tashish uchun mustahkam qadoq kerak'] where project_id = 'e1419726-cc75-4e37-a75a-8219566f2ff7';
update public.reward_tiers set title = 'Samarqand kobalt piyolasi va likopchasi', description = 'Qoʻlda yasalgan, anʼanaviy Samarqand naqshli sopol piyola. Usta imzosi bilan.', items = array['Sopol piyola', 'Likopcha', 'Kelib chiqish sertifikati'], estimated_delivery = '2026-yil dekabr',
  kind = 'reward', compare_at_amount = 450000, image_paths = array['/images/samarkand-craft.jpg'], long_description = 'Har bir piyola Mahmud aka tomonidan charxda qoʻlda yasaladi va kobalt sir bilan 1 180°C da kuydiriladi. Ostida usta muhri va raqam bor. Hajmi 220 ml. Idish yuvish mashinasida yuvsa boʻladi.',
  is_featured = false, is_digital = false, per_backer_limit = null, available_until = null
