update public.project_updates set title = 'Elektr pechda birinchi sinov — birorta nuqsonsiz', body = 'Kecha kulol ustamiz Mahmud aka 1 180°C dagi birinchi kuydirishdan keyin pech eshigini ochdi. Laganlardagi kobalt rang juda yorqin chiqdi.' where id = '84c2ebdc-654b-4950-ac7f-8f08cb00e3c5';
update public.comments set body = 'Ustalarimizni qoʻllab-quvvatlaganimdan xursandman! Roʻmol uchun homiy boʻlsak, ustaxonaga borsak boʻladimi?' where id = 'c1c1adcb-4ab7-4708-a464-14291fd74e7a';
update public.comments set body = 'Albatta, Gulnora opa! Samarqandga kelganingizda barcha homiylarni choy va shirinlik bilan kutib olamiz.' where id = '82d83034-083c-4ff6-aab3-e10af2b9bbf6';
update public.founder_profiles set display_name = 'Jasur Bekmurodov', role_title = 'Asoschi, robototexnika oʻqituvchisi', organization = '"Kelajak muhandislari" NNT', location = 'Toshkent', bio = 'Toshkentdagi Inha universiteti bitiruvchisi. 7 yildan beri yoshlar uchun muhandislik olimpiadalari tashkil qiladi.', registration_number = 'NNT reyestri № 1948203 (Adliya vazirligi)' where user_id = '04ead48c-9f90-4fd1-afd0-1600db4fb74f';
update public.projects set location = 'Chilonzor, Toshkent', cover_image_path = '/images/tashkent-robotics.jpg', original_language = 'uz' where id = '6f3e75b3-a961-4c02-a15d-d768311a82dc';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('6f3e75b3-a961-4c02-a15d-d768311a82dc', 'uz', 'Chilonzorda bolalar uchun bepul robototexnika laboratoriyasi', 'Toshkent davlat maktablarining 600 dan ortiq oʻquvchisiga robototexnika va dasturlashni bepul oʻrgatamiz.', 'Chilonzor tumanida ochiq laboratoriya: kam taʼminlangan oilalar farzandlari uchun robototexnika, 3D bosma va dasturlash boʻyicha bepul mashgʻulotlar.', 'Toshkentda minglab maktab oʻquvchilari muhandis boʻlishni orzu qiladi. Ammo kavsharlash stansiyasi, osillograf va 3D printer bor toʻgaraklar koʻp oilalar uchun qimmat.

Chilonzordagi 320 kv. metrlik binoni laboratoriyaga aylantirmoqdamiz. Hokimiyat binoni bepul berdi. Mashgʻulotlar, uskunalar va murabbiylar — hammasi tekin.

Yigʻilgan pulning hammasi uskunaga ketadi: 20 ta Arduino/ESP32 ish joyi, 6 ta 3D printer, himoya vositalari va oʻzbek hamda rus tilidagi oʻquv qoʻllanmalar.', 'Bolalar bilan ishlaganda uskunalar tez eskiradi. Byudjetning 15 foizi ehtiyot qismlarga ajratilgan. Kavsharlashdan oldin har bir oʻquvchi xavfsizlik boʻyicha yoʻriqnomadan oʻtadi.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = '6f3e75b3-a961-4c02-a15d-d768311a82dc')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
