update public.budget_items set category = '3D printerlar', description = '6 ta 3D printer va 100 kg biologik parchalanadigan PLA ip' where id = 'a2b98521-d34a-4562-af9b-49102aa6ce04';
update public.budget_items set category = 'Oʻzbek tilidagi oʻquv dasturi', description = 'Rasmli qoʻllanmalar va onlayn topshiriqlar' where id = '7dedbe99-0a86-455b-a96a-cfb10b0bfb40';
