update public.budget_items set category = 'Yillik musobaqa jamgʻarmasi', description = 'Toshkent yoshlari oʻrtasida robot-rover musobaqasi uchun materiallar' where id = 'd813f5e5-5562-4b56-a26a-836364f323fc';
update public.milestones set title = 'Chilonzordagi xonani taʼmirlash', description = 'Alohida elektr tarmogʻi, kuchlanish himoyasi va antistatik pol yotqizish.', target_label = '1-oy' where id = 'f5bfb86f-c511-496a-aa78-799e8783911c';
update public.milestones set title = 'Uskunalarni olish va oʻrnatish', description = '20 ta kavsharlash stansiyasi, 3D printerlarni yigʻish va ESP32 toʻplamlarini sinash.', target_label = '2-oy' where id = '50fa21bf-2c90-44b9-afad-824ea532f7ab';
update public.milestones set title = 'Birinchi guruh — 150 oʻquvchi', description = 'Qabulni ochish; oʻrinlarning bir qismi davlat maktabi oʻquvchilariga.', target_label = '3-oy' where id = 'd93f52a4-da32-494e-a0cb-581283b13684';
update public.milestones set title = 'Ochiq kun va koʻrgazma', description = 'Oʻquvchilar yasagan issiqxona datchiklari va mini-roverlarni ota-onalarga koʻrsatish.', target_label = '5-oy' where id = '90ee27c1-c7bd-4054-a80e-d000f9cabda3';
update public.evaluations set summary = 'Taʼlimga taʼsiri katta. NNT maqomi tekshirildi, hokimiyat bilan bepul bino boʻyicha shartnoma tasdiqlandi.', strengths = array['Inha va Turin universitetlari bitiruvchilaridan iborat koʻngilli jamoa', 'Toʻlov yoʻqligi sababli har qanday oila farzandi qatnasha oladi', 'Uskunalar 5 yildan ortiq, koʻp guruhlar uchun ishlatiladi'], risks = array['Kavsharlash uchlari, tishli gʻildiraklar kabi sarf materiallarini doim toʻldirish kerak'] where project_id = '6f3e75b3-a961-4c02-a15d-d768311a82dc';
update public.project_updates set title = 'Antistatik pol yotqizildi, 20 ta stol keldi', body = 'Sizning yordamingiz bilan Chilonzordagi xona haqiqiy laboratoriyaga aylandi! ESP32 va Arduino platalarining birinchi partiyasi bojxonadan kechikmasdan oʻtdi.' where id = '920bb183-49ad-486c-a80e-126d85ccf54b';
update public.comments set body = '12 yoshli qizim mashgʻulotlar boshlanishini intiqlik bilan kutyapti! Qoʻllab-quvvatlaganimdan faxrlanaman.' where id = '8195e566-1886-4a21-afa3-3c016502b04b';
update public.founder_profiles set display_name = 'Temur Dauletov', role_title = 'Ekolog, loyiha rahbari', organization = '"Orolni yashillashtirish" tashabbusi', location = 'Nukus', bio = '24 yildan beri Qoraqalpogʻiston va Ustyurtda choʻl ekologiyasi va tuproqni tiklash bilan shugʻullanadi.', registration_number = 'Ilmiy-tadqiqot markazi № 049281' where user_id = 'ccd673df-5d87-4db1-ae1c-e9cba10c701b';
update public.projects set location = 'Moʻynoq, Qoraqalpogʻiston', cover_image_path = '/images/projects/aral-saxaul.jpg', original_language = 'uz' where id = '34fae723-c786-42f9-af7b-50f70a21ada1';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('34fae723-c786-42f9-af7b-50f70a21ada1', 'uz', 'Orol qurigan tubiga 50 000 saksovul', 'Moʻynoqda tuzli changni toʻxtatadigan saksovul toʻsigʻini ekamiz: 13 000 soʻm — bitta koʻchat.', 'Moʻynoq tumanida chuqur ildizli qora saksovul ekib, qumni mustahkamlaymiz va tuzli chang boʻronlarini kamaytiramiz.', 'Orol dengizi qurib, oʻrnida Orolqum choʻli paydo boʻldi. Har yili u yerdan havoga 75 million tonnadan ortiq tuz va chang koʻtariladi. Qora saksovulning ildizi 12 metr chuqurlikka boradi — qumni ushlab, namlikni saqlaydi.

Qoraqalpoq davlat universiteti olimlari bilan birga GPS yordamida egat ochib ekish usulini ishlab chiqdik. Ogʻir sharoitda ham koʻchatlarning 82 foizi tutib ketadi.

Har 13 000 soʻm bitta sertifikatlangan koʻchatni ekish va ikki yil parvarishlashga yetadi. Homiylar oʻz uchastkasining GPS koordinatalari va har yili sunʼiy yoʻldosh orqali oʻsimlik qoplami hisobotini oladi.', 'Erta bahordagi boʻronlar yangi koʻchatlarni qum bilan koʻmib yuborishi mumkin. Shuning uchun koʻchatlarni tuzli shamoldan toʻsadigan pogʻonali kichik ariqlarga ekamiz.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = '34fae723-c786-42f9-af7b-50f70a21ada1')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
update public.budget_items set category = '50 000 ta sertifikatlangan saksovul koʻchati', description = 'Qoʻngʻirotdagi choʻl koʻchatxonasida yetishtirilgan' where id = '38b0822c-aa89-4c43-a571-789d45774b02';
update public.budget_items set category = 'Traktor yoqilgʻisi va egat ochish', description = 'Qumda ekish texnikasi uchun yoqilgʻi va taʼmirlash' where id = '71fea431-b42e-439c-a809-3fad1103a8c7';
update public.budget_items set category = 'Mahalliy ekish brigadalari', description = 'Moʻynoqning 30 nafar aholisiga mavsumiy ish haqi' where id = '93f45649-75dd-49ea-a098-971aae8eae00';
update public.budget_items set category = 'Sunʼiy yoʻldosh va dron monitoringi', description = 'Dron parvozlari va Sentinel-2 suratlari tahlili' where id = '8cb1e7d5-ce1f-4d1c-ada3-e59f0337b21d';
update public.milestones set title = 'Koʻchatlarni chiniqtirish', description = 'Qoʻngʻirot koʻchatxonasida 50 000 ta ikki yillik koʻchatni saralash.', target_label = '1-oy' where id = '3551852a-1b20-457e-a35b-2d4cf60153d4';
update public.milestones set title = 'Birinchi ekish — 25 000 daraxt', description = 'Janubiy qismdagi 4B uchastkasiga ekish.', target_label = '2-oy' where id = '6bbdaf21-a427-40aa-abd9-201ed41355d4';
update public.milestones set title = 'Ikkinchi ekish — 25 000 daraxt', description = 'Shimoliy himoya chizigʻini ekib boʻlish.', target_label = '3-oy' where id = 'b352c429-18f7-44d3-a3a6-b648ca95198d';
update public.milestones set title = 'Bahorgi sanoq va ochiq hisobot', description = 'Tutgan daraxtlar xaritasini va homiylar uchun GPS sahifani eʼlon qilish.', target_label = '6-oy' where id = '83da2a2a-af98-4209-a280-447a08edd583';
update public.evaluations set summary = 'Ilmiy asosi mustahkam, bir daraxt narxi ochiq hisoblangan. Viloyat oʻrmon xoʻjaligi qoʻllab-quvvatlaydi.', strengths = array['20 yilda sinalgan, 82% tutish natijasini beradigan usul', 'Moʻynoq aholisi uchun ish oʻrinlari', 'Sunʼiy yoʻldosh orqali ochiq tekshiruv'], risks = array['Erta bahordagi issiq kunlarda namlik saqlovchi gel kerak boʻladi'] where project_id = '34fae723-c786-42f9-af7b-50f70a21ada1';
update public.project_updates set title = '4B uchastkasiga 25 000 koʻchat ekildi!', body = 'Jamoamiz sovuq choʻl shamoliga qaramay janubiy uchastkani muddatidan oldin ekib boʻldi. Oktabr yomgʻirlaridan keyin tuproq namligi aynan kerakli darajada.' where id = '01dc493b-8eb3-45f4-a0f5-791f1318a142';
update public.comments set body = 'Orol — hammamizning masʼuliyatimiz. Temur aka, umringizni shu ishga bagʻishlaganingiz uchun rahmat.' where id = 'fd8537e1-40df-4abd-a78f-953a6476745d';
update public.founder_profiles set display_name = 'Bobur Alimov', role_title = 'Boshqaruvchi hamkor', organization = '"Zarafshon Green Tech" MChJ', location = 'Navoiy', bio = 'Qayta tiklanuvchi energiya muhandisi. 14 yildan beri yirik quyosh elektr stansiyalari va sanoat sovutgichlari loyihalarida ishlaydi.', registration_number = 'MChJ guvohnomasi № 308194821 (Navoiy erkin iqtisodiy zonasi)' where user_id = '6c5a0045-2cc6-41de-abfe-5c41c830650f';
update public.projects set location = 'Karmana, Navoiy viloyati', cover_image_path = '/images/projects/zarafshan-fruit.jpg', original_language = 'uz' where id = 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', 'uz', 'Zarafshon: quyosh energiyasida ishlaydigan meva omborlari', 'Navoiy va Buxoro bogʻdorlari uchun 150 tonnalik sovutgichli omborlar — elektr tarmogʻiga bogʻliq emas.', 'Kichik fermerlar hosilni mavsumda arzonga sotib yubormasligi uchun bogʻlar yonida quyosh energiyali sovutgich omborlar quramiz. Toʻlov — har bir yashik uchun.', 'Uzum, anor va oʻrik yetishtiramiz, lekin kichik oilaviy xoʻjaliklar hosilning 30 foizigacha qismini yoʻqotadi. Saqlash joyi yoʻqligi uchun terim paytida eng past narxda sotishga majbur boʻladi.

Zarafshon vodiysida bogʻlar yonida 150 tonnalik modulli sovutgich omborlar quramiz. Ular quyosh panellari va muzli issiqlik akkumulyatorida ishlaydi: elektr oʻchsa ham ichkarida doim 0–4°C.

Bu mushoraka loyihasi: sarmoyadorlar ombor egalaridan biriga aylanadi va yashik saqlash hamda saralash xizmatlaridan tushgan tekshirilgan foydaning 26 foizini yiliga ikki marta oladi.', 'Uskunani chetdan olib kelish muddati oʻzgarishi mumkin. Shuning uchun barcha sovutgich uskunalarini Toshkentdagi rasmiy distribyutorlar orqali, ishlab chiqaruvchi kafolati bilan oldik.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
