update public.evaluations set summary = 'Navoiy va Buxoroda hosildan keyingi saqlash joyi yetishmasligi tasdiqlangan, daromad har yili takrorlanadi. Kompaniya Navoiy erkin iqtisodiy zonasida toʻgʻri roʻyxatdan oʻtgan.', strengths = array['Muzli akkumulyator tufayli elektr toʻlovlari deyarli yoʻq', 'Karmana tumanidagi 18 ta uzumzor egasi bilan niyat bayonnomasi imzolangan', 'Mablagʻ koʻchmas mulk va uskuna koʻrinishida saqlanadi'], risks = array['Yozgi terim va qishki taʼmirlash oylari orasida daromad oʻzgarib turadi'] where project_id = 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538';
