update public.projects set location = 'Chust, Namangan viloyati', cover_image_path = '/images/projects/chust-knives.jpg', original_language = 'uz' where id = 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 'uz', 'Chust pichogʻi: qoʻlda toblangan damask poʻlat', 'Chust pichoqchilik anʼanasini damask poʻlat bilan boyitamiz — oshxona va kolleksiya uchun.', 'Namangan viloyati Chust shahridagi 12 nafar usta pichoqchiga gidravlik bolgʻa va jilolash uskunalari olib beramiz.', 'Chust pichogʻi jez naqshi va shox dastasi bilan butun dunyoga mashhur. Asrlar davomida ular qoʻlda, bolgʻa bilan toblanib keladi.

Bugungi oshxonada raqobatlashish uchun ustalarimiz anʼanaviy Chust dastasini koʻp qatlamli, yuqori uglerodli damask poʻlat bilan birlashtirmoqda.

Homiylar har biri raqamlangan, qoʻlda yasalgan pichoq oladi: oshxona pichogʻi, osh uchun anʼanaviy pichoq va Chust ustalari tikkan charm gʻilof.', 'Har bir pichoq qoʻlda yasaladi, shuning uchun damask naqshi va yogʻoch tolasi biroz farq qiladi — bu haqiqiy qoʻl mehnatining belgisi.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
