update public.founder_profiles set display_name = 'Shahnoza Qosimova', role_title = 'Oʻquv dasturi rahbari', organization = '"Registon raqamli" jamgʻarmasi', location = 'Samarqand', bio = 'Xalqaro matematika olimpiadasi sovrindorlarining murabbiyi, 12 yillik tajribaga ega pedagog.', registration_number = 'NNT № 2049182 (Maktabgacha va maktab taʼlimi vazirligi hamkori)' where user_id = '892102a8-5a9e-42b7-a542-c4200755a6a3';
update public.projects set location = 'Samarqand va Toshkent', cover_image_path = '/images/projects/registan.jpg', original_language = 'uz' where id = '73cf3516-836c-478a-a790-35b6270b9ae2';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('73cf3516-836c-478a-a790-35b6270b9ae2', 'uz', 'Registon: oʻzbek tilida moslashuvchan matematika', '5–11-sinflar uchun davlat dasturiga mos, oʻyin shaklidagi matematika ilovasi.', '10 000 dan ortiq masala, oʻzbek tilidagi animatsion video darslar va 50 ta davlat maktabi uchun avtomatik bilim tekshiruvi.', 'Xorijiy matematika ilovalari koʻp, lekin ular Oʻzbekiston maktab dasturiga mos emas va oʻzbek tilida tabiiy gapirmaydi.

Registon arzon Android telefonlarda ham, sekin internetda ham bemalol ishlaydigan yengil ilova yaratmoqda. Oʻqituvchi har bir oʻquvchi qaysi mavzuni oʻzlashtirganini real vaqtda koʻradi.

Bu notijorat loyiha: Samarqand, Qashqadaryo va Surxondaryo qishloqlaridagi 12 000 nafar oʻquvchi ilovadan bepul foydalanadi.', 'Qishloq maktablarida internet tez-tez uziladi. Ilova internetsiz ishlaydi va natijalarni aloqa tiklanganda sinxronlaydi.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = '73cf3516-836c-478a-a790-35b6270b9ae2')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
