update public.milestones set title = 'Ovozlashtirish va toʻliq ishga tushirish', description = 'Yuqori sinflar uchun algebra va geometriya boʻlimlarini chiqarish.', target_label = '3-oy' where id = 'c755e49b-5d40-4e84-af44-1132b061562c';
update public.milestones set title = 'Yil yakuni olimpiadasi va natijalar', description = 'Oʻquvchilar bilimi qanchalik oshganini homiylarga eʼlon qilish.', target_label = '6-oy' where id = '5df6d7f2-1dc1-465c-a7e0-738507ba24cc';
update public.evaluations set summary = 'Ijtimoiy taʼsiri yuqori. Viloyat taʼlim boshqarmalari bilan hamkorlik yoʻlga qoʻyilgan, sinov bosqichida oʻquvchilar darslarni oxirigacha oʻtgan.', strengths = array['Oʻzbek tilidagi, mahalliy hayotga yaqin kontent — bu boʻshliqni toʻldiradi', 'Bir oʻquvchiga yiliga taxminan 7 500 soʻm sarflanadi'], risks = array['Maktablarda internet uzilib turgani uchun internetsiz rejim ishonchli boʻlishi kerak'] where project_id = '73cf3516-836c-478a-a790-35b6270b9ae2';
update public.project_updates set title = '7-sinf geometriyasi boʻyicha interaktiv darslar sinovga chiqdi', body = 'Endi oʻquvchilar 3D shakllarni ekranda aylantirib koʻra oladi, hamma narsa oʻzbek tilida ovozli tushuntiriladi.' where id = '43234a23-cdd2-482e-abdd-52059f5764bd';
update public.founder_profiles set display_name = 'Sardor Mirzayev', role_title = 'Asoschi, bosh muhandis', organization = '"Andijan Mobility" MChJ', location = 'Andijon', bio = 'Asakadagi avtomobil zavodida 12 yil ishlab chiqarish va dvigatel sinovlari bilan shugʻullangan.', registration_number = 'MChJ guvohnomasi № 309482103 (Andijon sanoat zonasi)' where user_id = '86361a3b-797e-4827-a46b-5652b846d9d3';
update public.projects set location = 'Andijon', cover_image_path = '/images/projects/andijan-trike.jpg', original_language = 'uz' where id = '3107824e-03ea-4634-a63a-a6f273994879';
insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
  select v.project_id::uuid, v.language::public.app_language, v.title, v.tagline, v.summary, v.story, v.risks
  from (values ('3107824e-03ea-4634-a63a-a6f273994879', 'uz', 'Andijon: uch gʻildirakli elektr yuk mototsikllari', 'Bozor savdogarlari va fermerlar uchun Andijonda yigʻilgan elektr yuk mototsikllari.', 'Shovqinli, benzin yeydigan yuk mototsikllari oʻrniga oddiy 220V rozetkadan bir kechada quvvatlanib, 600 kg yuk tashiydigan elektr mototsikllar.', 'Bozorlarda va dehqon xoʻjaliklarida uch gʻildirakli yuk mototsikllari meva-sabzavot, mato va non tashishda juda muhim. Ammo benzin va tez-tez taʼmirlash haydovchilarga qimmatga tushadi.

Andijon Mobility mahalliy poʻlat rama va litiy-temir-fosfat batareyali elektr mototsikllar yasaydi. Bir kilometr yoʻl benzinli mototsikldan 80% arzonga tushadi.

Bu mushoraka loyihasi: Andijonda 200 ta mototsikl yigʻadigan liniya quramiz. Sarmoyadorlar mototsikl sotuvi va batareya almashtirish xizmatidan tushgan sof foydaning 24 foizini oladi.', 'Batareya elementlarini olib kelish temir yoʻl kechikishlariga bogʻliq boʻlishi mumkin. Andijondagi omborimizda 60 kunlik zaxira saqlaymiz.')) v(project_id, language, title, tagline, summary, story, risks)
  where exists (select 1 from public.projects where id = '3107824e-03ea-4634-a63a-a6f273994879')
  on conflict (project_id, language) do update set title = excluded.title, tagline = excluded.tagline,
    summary = excluded.summary, story = excluded.story, risks = excluded.risks;
