update public.evaluations set summary = 'Mahalliy ishlab chiqarish iqtisodi puxta hisoblangan. Bozor yuk tashuvchilari kooperativlaridan talab katta.', strengths = array['Asaka avtomobil zavodidan kelgan kuchli muhandislik tajribasi', 'Benzinli mototsiklga nisbatan arzonligi sababli xaridor 7 oyda xarajatini qoplaydi'], risks = array['Batareya yetkazib berish oʻzgarib turadi — mahalliy zaxira kerak'] where project_id = '3107824e-03ea-4634-a63a-a6f273994879';
update public.project_updates set title = 'Rama 1 000 kg yuk sinovidan oʻtdi', body = 'Mustahkamlangan rama ruxsat etilgan yukdan 1,5 baravar ogʻir yuk ostida ham egilmadi. Batareya mahkamlagichlari sertifikatlandi.' where id = 'b0548cce-9d05-48ec-ad6c-29f10d1a4bf3';
